    12→struct MessageForwardingScreenCoordinatorParameters {
    13→    let forwardingItem: MessageForwardingItem
    14→    let userSession: UserSessionProtocol
    15→    let roomSummaryProvider: RoomSummaryProviderProtocol
    16→    let userIndicatorController: UserIndicatorControllerProtocol
    17→}
    18→
    19→enum MessageForwardingScreenCoordinatorAction {
    20→    case dismiss
    21→    case sent(roomID: String)
    22→}
    23→
    24→final class MessageForwardingScreenCoordinator: CoordinatorProtocol {
    25→    private var viewModel: MessageForwardingScreenViewModelProtocol
    26→    private let actionsSubject: PassthroughSubject<MessageForwardingScreenCoordinatorAction, Never> = .init()
    27→    private var cancellables = Set<AnyCancellable>()
    28→    
    29→    var actions: AnyPublisher<MessageForwardingScreenCoordinatorAction, Never> {
    30→        actionsSubject.eraseToAnyPublisher()
    31→    }
    32→    
    33→    init(parameters: MessageForwardingScreenCoordinatorParameters) {
    34→        viewModel = MessageForwardingScreenViewModel(forwardingItem: parameters.forwardingItem,
    35→                                                     userSession: parameters.userSession,
    36→                                                     roomSummaryProvider: parameters.roomSummaryProvider,
    37→                                                     userIndicatorController: parameters.userIndicatorController)
    38→    }
    39→    
    40→    func start() {
    41→        viewModel.actions.sink { [weak self] action in
    42→            switch action {
    43→            case .dismiss:
    44→                self?.actionsSubject.send(.dismiss)
    45→            case .sent(let roomID):
    46→                self?.actionsSubject.send(.sent(roomID: roomID))
    47→            }
    48→        }
    49→        .store(in: &cancellables)
    50→    }
    51→        
    52→    func toPresentable() -> AnyView {
    53→        AnyView(MessageForwardingScreen(context: viewModel.context))
    54→    }
    55→    
    56→    func stop() {
    57→        viewModel.stop()
    58→    }
    59→}
